CREATE OR REPLACE FUNCTION public.finalize_stripe_order_payment(_order_id uuid, _checkout_session text, _payment_intent text, _charge text, _amount_total integer, _tax_cents integer, _payment_status text, _offer_id uuid DEFAULT NULL::uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$BEGIN
 PERFORM public.assert_current_account_access(); -- bluebird-account-boundary-v1

DECLARE o public.orders; expected integer;
BEGIN
  PERFORM set_config('parkvault.trusted_operation', 'on', true);
  SELECT * INTO o FROM public.orders WHERE id = _order_id FOR UPDATE;
  IF o.id IS NULL THEN RAISE EXCEPTION 'Order not found'; END IF;
  IF o.stripe_payment_intent_id IS NOT NULL AND o.stripe_payment_intent_id <> _payment_intent THEN
    RAISE EXCEPTION 'Payment intent mismatch';
  END IF;
  IF o.payment_authorized THEN
    PERFORM set_config('parkvault.trusted_operation', 'off', true);
    RETURN;
  END IF;
  IF o.status <> 'awaiting_payment' THEN
    RAISE EXCEPTION 'Order reservation is no longer payable';
  END IF;
  IF o.ask_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.asks a
     WHERE a.id = o.ask_id AND a.status = 'matched' AND a.matched_order_id = o.id
  ) THEN
    RAISE EXCEPTION 'Exact listing reservation is no longer owned by this order';
  END IF;
  expected := o.merchandise_cents + o.buyer_fee_cents + o.shipping_cents + _tax_cents;
  IF expected <> _amount_total THEN RAISE EXCEPTION 'Stripe total does not match order total'; END IF;

  UPDATE public.orders
     SET tax_cents = _tax_cents, total_cents = _amount_total,
         fee_snapshot = fee_snapshot || jsonb_build_object(
           'tax_cents', _tax_cents, 'shipping_and_tax_calculated', true,
           'total_cents', _amount_total),
         stripe_checkout_session_id = _checkout_session,
         stripe_payment_intent_id = _payment_intent,
         stripe_charge_id = nullif(_charge, ''),
         stripe_payment_status = _payment_status,
         stripe_captured_at = now(), payment_authorized = true,
         status = 'payment_captured', reservation_expires_at = NULL,
         checkout_expires_at = NULL
   WHERE id = o.id;

  INSERT INTO public.order_payments (
    order_id, kind, provider, external_reference, amount_cents, currency,
    provider_status, recorded_by, note
  ) VALUES (
    o.id, 'payment', 'stripe', _payment_intent, _amount_total, o.currency,
    'succeeded', o.buyer_id, 'Captured by ParkVault Checkout.'
  ) ON CONFLICT DO NOTHING;

  INSERT INTO public.order_payouts (
    order_id, payee_id, provider, amount_cents, currency, status, recorded_by, note
  ) VALUES (
    o.id, o.seller_id, 'stripe_connect', o.payout_cents, o.currency, 'pending',
    o.buyer_id, 'Held by ParkVault until delivery and the inspection window are complete.'
  ) ON CONFLICT (order_id) DO NOTHING;

  INSERT INTO public.order_events (order_id, actor_id, from_status, to_status, note)
  VALUES (o.id, NULL, o.status, 'payment_captured',
    'Payment captured securely by Stripe. Payout remains pending.');

  IF _offer_id IS NOT NULL THEN
    UPDATE public.listing_offers
       SET status = 'accepted', stripe_checkout_session_id = _checkout_session,
           stripe_payment_intent_id = _payment_intent,
           stripe_charge_id = nullif(_charge, ''),
           stripe_payment_status = 'captured', updated_at = now()
     WHERE id = _offer_id;
  END IF;

  IF o.ask_id IS NOT NULL THEN
    UPDATE public.listing_offers
       SET status = 'declined',
           stripe_payment_status = CASE
             WHEN (stripe_payment_intent_id IS NOT NULL OR stripe_checkout_session_id IS NOT NULL)
              AND coalesce(stripe_payment_status, '') NOT IN ('canceled', 'captured')
               THEN 'cancel_pending'
             ELSE stripe_payment_status
           END,
           updated_at = now()
     WHERE ask_id = o.ask_id
       AND (_offer_id IS NULL OR id <> _offer_id)
       AND status IN ('pending', 'countered');
  END IF;

  IF o.origin = 'sourcing_shopper' THEN
    UPDATE public.sourcing_assignments SET status = 'assigned', updated_at = now()
     WHERE order_id = o.id;
    PERFORM public.notify_member(o.seller_id, 'sourcing_job', 'New shopping job',
      'A buyer has paid for you to source an item. Open Park Shopper to start shopping.', o.id);
    PERFORM public.notify_member(o.buyer_id, 'payment_captured', 'Shopping job confirmed',
      'Your Park Shopper has been notified and will start shopping.', o.id);
  ELSE
    PERFORM public.notify_member(o.seller_id, 'order_paid', 'Your item sold',
      'Payment is complete. Open the order for shipping instructions.', o.id);
    PERFORM public.notify_member(o.buyer_id, 'payment_captured', 'Purchase confirmed',
      'Your ParkVault payment was successful.', o.id);
  END IF;
  PERFORM set_config('parkvault.trusted_operation', 'off', true);
END;
END;$function$

