CREATE OR REPLACE FUNCTION public.guard_pilot_writes()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NOT public.is_trusted_operation() THEN
    RAISE EXCEPTION 'This record is maintained by ParkVault pilot operations and cannot be changed directly'
      USING errcode = '42501';
  END IF;
  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  RETURN NEW;
END $function$

CREATE OR REPLACE FUNCTION public.guard_pilot_writes()
